const CYAN = 0x00d5d5, GREEN = 0x33cc33, RED = 0xdd0000;
const g3 = new THREE.Group(); scene.add(g3);          // 3D-mode content
const charts = new THREE.Group(); scene.add(charts);  // 2D-mode content
charts.visible = false;

// ---- world plane (Z=0), plane coords X∈[0,6], Y∈[0,4], tilted about in-plane Y axis
const planeGroup = new THREE.Group(); g3.add(planeGroup);
{
  const surf = new THREE.Mesh(new THREE.PlaneGeometry(6, 4),
    new THREE.MeshBasicMaterial({ color: 0xd9d9d9, side: THREE.DoubleSide }));
  surf.position.set(3, 2, 0); planeGroup.add(surf);
