  planeGroup.add(wf(new THREE.Vector3(0, 1, 0), 1.3));
  planeGroup.add(wf(new THREE.Vector3(0, 0, 1), 1.3));
}
// world point (local, rotates with plane)
const wpRim = new THREE.Mesh(new THREE.SphereGeometry(.12, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
const wpDot = new THREE.Mesh(new THREE.SphereGeometry(.09, 16, 12), new THREE.MeshBasicMaterial({ color: CYAN }));
wpRim.position.set(3, 1.6, .05); wpDot.position.set(3, 1.6, .07);
planeGroup.add(wpRim, wpDot);
registerInteractive(wpDot, { title: 'World point (X,Y,0)', body: 'A point on the planar surface. Because Z=0 for every surface point, its full 3D coordinates carry only two degrees of freedom — the homography maps (X,Y) directly to the image (x,y).' });

// ---- camera center
let camC = new THREE.Vector3(-2.5, 2.5, 4.5);
const lookTarget = new THREE.Vector3(3, 1.5, 0);
const camSphere = new THREE.Mesh(new THREE.SphereGeometry(.14, 20, 14), new THREE.MeshBasicMaterial({ color: 0x111111 }));
g3.add(camSphere);
registerInteractive(camSphere, { title: 'Camera center', tooltip: 'Drag to move the camera', body: 'The center of projection. Every scene point is imaged along a ray through this point. Drag it: the projection (x,y) and every entry of H change continuously — H depends on the camera pose relative to the plane.' });

// ---- image plane group (rebuilt per update)
const imgMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: .25, side: THREE.DoubleSide, depthWrite: false });
const imgPlane = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), imgMat); g3.add(imgPlane);
const imgBorder = new THREE.LineLoop(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x111111 })); g3.add(imgBorder);
const patch = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({ color: 0xbfbfbf, side: THREE.DoubleSide })); g3.add(patch);
const ipRim = new THREE.Mesh(new THREE.SphereGeometry(.09, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
const ipDot = new THREE.Mesh(new THREE.SphereGeometry(.07, 16, 12), new THREE.MeshBasicMaterial({ color: CYAN }));
g3.add(ipRim, ipDot);
registerInteractive(ipDot, { title: 'Image point (x,y)', body: 'The projection of (X,Y,0) onto the camera plane. Computed from the homography: [x y 1]ᵀ ~ H·[X Y 1]ᵀ, de-homogenized by dividing by the third coordinate.' });
registerInteractive(imgPlane, { title: 'Camera plane', body: 'The image plane at focal distance from the camera center. All projection rays pierce it; the grey patch is a local image window around the projected point.' });

// green camera frame arrows
const gAxisX = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(), .8, GREEN, .16, .09);
const gAxisY = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(), .8, GREEN, .16, .09);
g3.add(gAxisX, gAxisY);

// ---- rays
function dashedLine(color, dash = .18, gap = .12) {
  const l = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineDashedMaterial({ color, dashSize: dash, gapSize: gap }));
  g3.add(l); return l;
}
const cyanRay = dashedLine(CYAN, .22, .14);
const frustum = [dashedLine(0x111111), dashedLine(0x111111), dashedLine(0x111111), dashedLine(0x111111)];
function setLine(l, a, b) {
  l.geometry.dispose();
  l.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
  l.computeLineDistances();
}

// ---- homography math: H = K[r1 r2 t], tilt rotates world X axis about Y
const fx = 300, fy = 300;
let tiltDeg = 0;
const _e1 = new THREE.Vector3(), _e2 = new THREE.Vector3(0, 1, 0);
function computeH() {
  const f = lookTarget.clone().sub(camC).normalize();
  const r = new THREE.Vector3().crossVectors(f, new THREE.Vector3(0, 1, 0)).normalize();
  const u = new THREE.Vector3().crossVectors(r, f);
  const th = THREE.MathUtils.degToRad(tiltDeg);
  _e1.set(Math.cos(th), 0, -Math.sin(th));
  const col = v => [fx * r.dot(v), fy * u.dot(v), f.dot(v)];
  const h1 = col(_e1), h2 = col(_e2), h3 = col(camC.clone().negate());
  let H = [[h1[0], h2[0], h3[0]], [h1[1], h2[1], h3[1]], [h1[2], h2[2], h3[2]]];
  const s = H[2][2] || 1e-9;
  H = H.map(row => row.map(x => x / s));
  return { H, r, u, f };
}
function applyH(H, X, Y) {
  const w = H[2][0] * X + H[2][1] * Y + H[2][2];
  return [(H[0][0] * X + H[0][1] * Y + H[0][2]) / w, (H[1][0] * X + H[1][1] * Y + H[1][2]) / w];
}
const wp = (X, Y) => _e1.clone().multiplyScalar(X).add(_e2.clone().multiplyScalar(Y));

// ---- 2D charts
const leftChart = new THREE.Group(); leftChart.position.set(-3.9, -1.1, 0); charts.add(leftChart);
const rightChart = new THREE.Group(); rightChart.position.set(1.6, -1.1, 0); charts.add(rightChart);
{
  const s = .5, gp = [];
  for (let i = 0; i <= 12; i++) gp.push(new THREE.Vector3(i * .5 * s, 0, 0), new THREE.Vector3(i * .5 * s, 4 * s, 0));
  for (let j = 0; j <= 8; j++) gp.push(new THREE.Vector3(0, j * .5 * s, 0), new THREE.Vector3(6 * s, j * .5 * s, 0));
  leftChart.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(gp), new THREE.LineBasicMaterial({ color: 0x999999 })));
  const bp = [new THREE.Vector3(0, 0, .002), new THREE.Vector3(3, 0, .002), new THREE.Vector3(3, 2, .002), new THREE.Vector3(0, 2, .002)];
  leftChart.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(bp), new THREE.LineBasicMaterial({ color: 0x222222 })));
  const d1 = new THREE.Mesh(new THREE.CircleGeometry(.07, 20), new THREE.MeshBasicMaterial({ color: CYAN }));
  d1.position.set(3 * s, 1.6 * s, .005); leftChart.add(d1);
}
const guideLine = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineDashedMaterial({ color: 0x999999, dashSize: .12, gapSize: .1 }));
charts.add(guideLine);
function rebuildRightChart(H) {
  while (rightChart.children.length) {
    const c = rightChart.children.pop();
    c.geometry?.dispose?.(); c.material?.dispose?.();
  }
  const raw = [];
  for (let j = 0; j <= 8; j++) for (let i = 0; i <= 12; i++) raw.push(applyH(H, i * .5, j * .5));
  let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  raw.forEach(p => { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); });
  const s = 3.4 / Math.max(x1 - x0, y1 - y0, 1e-9);
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  const map = p => new THREE.Vector3((p[0] - cx) * s + 1.7, (p[1] - cy) * s + 1.0, 0);
  const seg = [];
  for (let j = 0; j <= 8; j++) for (let i = 0; i < 12; i++) seg.push(map(raw[j * 13 + i]), map(raw[j * 13 + i + 1]));
  for (let i = 0; i <= 12; i++) for (let j = 0; j < 8; j++) seg.push(map(raw[j * 13 + i]), map(raw[(j + 1) * 13 + i]));
  rightChart.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(seg), new THREE.LineBasicMaterial({ color: 0x999999 })));
  const corners = [[0, 0], [6, 0], [6, 4], [0, 4]].map(c => map(applyH(H, c[0], c[1])));
  rightChart.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(corners), new THREE.LineBasicMaterial({ color: 0x222222 })));
  const dot = map(applyH(H, 3, 1.6));
  const dm = new THREE.Mesh(new THREE.CircleGeometry(.07, 20), new THREE.MeshBasicMaterial({ color: CYAN }));
  dm.position.copy(dot).setZ(.005); rightChart.add(dm);
  // guide between corresponding points
  const a = leftChart.position.clone().add(new THREE.Vector3(1.5, .8, 0));
  const b = rightChart.position.clone().add(dot);
  guideLine.geometry.dispose();
  guideLine.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
  guideLine.computeLineDistances();
}

// ---- master update
let curH = null;
function updateAll() {
  planeGroup.rotation.y = THREE.MathUtils.degToRad(tiltDeg);
  camSphere.position.copy(camC);
  const { H, r, u, f } = computeH(); curH = H;
  // project world corners → image plane bounds
